fn solve(word: Vec<char>) -> Vec<char> {
    // Define the two sets as constant arrays for membership checking.
    // Since all letters are uppercase English letters, we can directly check membership with a match.
    // Set A contains: A, E, F, H, I, K, L, M, N, T, V, W, X, Y, Z
    // Set B contains: B, C, D, G, J, O, P, Q, R, S, U
    
    // Helper closures to check membership in each set
    let is_in_set_a = |c: char| matches!(c, 
        'A' | 'E' | 'F' | 'H' | 'I' | 'K' | 'L' | 'M' | 'N' | 'T' | 'V' | 'W' | 'X' | 'Y' | 'Z');
    let is_in_set_b = |c: char| matches!(c, 
        'B' | 'C' | 'D' | 'G' | 'J' | 'O' | 'P' | 'Q' | 'R' | 'S' | 'U');

    // Edge case: input length is guaranteed 1..=10, so no need to handle empty input

    // Check the set membership of the first character
    let first_char = word[0];
    let first_in_a = is_in_set_a(first_char);
    let first_in_b = is_in_set_b(first_char);

    // If the first character is in neither set (should not happen per problem statement), return "NO"
    if !first_in_a && !first_in_b {
        return vec!['N', 'O'];
    }

    // Now verify all characters belong to the same set as the first character
    let all_match = if first_in_a {
        word.iter().all(|&c| is_in_set_a(c))
    } else {
        word.iter().all(|&c| is_in_set_b(c))
    };

    if all_match {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}